function check(input, actual, expected) {
  const [groupSizes] = input;
  const n = groupSizes.length;
  if (!Array.isArray(actual)) return false;
  const seen = new Array(n).fill(false);
  let placed = 0;
  for (const group of actual) {
    if (!Array.isArray(group) || group.length === 0) return false;
    for (const person of group) {
      if (!Number.isInteger(person) || person < 0 || person >= n || seen[person]) return false;
      if (groupSizes[person] !== group.length) return false;
      seen[person] = true;
      placed++;
    }
  }
  return placed === n;
}

