function validate([groupSizes]) {
  const n = groupSizes.length;
  if (n < 1 || n > 500) return 'groupSizes needs 1 to 500 values.';
  if (groupSizes.some(v => !Number.isInteger(v) || v < 1 || v > n)) return 'Each group size is a whole number from 1 to n.';
  const counts = new Map();
  for (const size of groupSizes) counts.set(size, (counts.get(size) ?? 0) + 1);
  for (const [size, count] of counts) if (count % size !== 0) return `The people asking for groups of ${size} cannot be split evenly.`;
  return null;
}

