function groupThePeople(groupSizes) {
  // Sort people by the group size they need, then cut the sorted list into consecutive chunks.
  const order = groupSizes.map((size, person) => person).sort((a, b) => groupSizes[a] - groupSizes[b] || a - b);
  const groups = [];
  let i = 0;
  while (i < order.length) {
    const size = groupSizes[order[i]];
    groups.push(order.slice(i, i + size));
    i += size;
  }
  return groups;
}

