function generate(rand, size) {
  const n = size === 'large' ? 500 : 1 + Math.floor(rand() * 10);
  // Cap the group sizes in different ways so some inputs are all singletons and some have one huge group.
  const style = rand();
  const cap = style < 0.15 ? 1 : style < 0.3 ? n : style < 0.65 ? 1 + Math.floor(rand() * Math.min(n, 6)) : 1 + Math.floor(rand() * n);
  const sizes = [];
  let left = n;
  while (left > 0) {
    const s = 1 + Math.floor(rand() * Math.min(cap, left));
    sizes.push(s);
    left -= s;
  }
  const people = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [people[i], people[j]] = [people[j], people[i]];
  }
  const groupSizes = new Array(n);
  let at = 0;
  for (const s of sizes) for (let k = 0; k < s; k++) groupSizes[people[at++]] = s;
  return [groupSizes];
}
